const paths={message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/>',pin:'<path d="M12 17v5M5 17h14v-2l-3-3V5l1-1V3H7v1l1 1v7l-3 3z"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18"/><ellipse cx="12" cy="12" rx="4" ry="9"/>',review:'<circle cx="6" cy="3" r="2"/><path d="M6 5v14M18 6a4 4 0 0 0-4-4m4 4v13"/><circle cx="6" cy="21" r="2"/><circle cx="18" cy="21" r="2"/>',book:'<path d="M12 7v14M3 3h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5v16h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',check:'<path d="m5 12 4 4L19 6"/>',checks:'<path d="m3 6 2 2 4-4M13 6h8M3 16l2 2 4-4M13 16h8"/>',down:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 6 6 6-6 6"/>',back:'<path d="m15 6-6 6 6 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]}</svg>`;

document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const state=document.body.dataset.state;const isChat=state==='chat';
const original=[{key:'home',title:'Project home',host:'example.test',icon:'globe',section:null},{key:'dev',title:'Development preview',host:'preview.example.test',icon:'globe',section:'preview',reason:'Mobile navigation is ready to try.'},{key:'pr',title:'Review changes',host:'github.com',icon:'review',section:'review',reason:'Spacing feedback addressed.'},{key:'stage',title:'Staging',host:'staging.example.test',icon:'globe',section:'preview'},{key:'notes',title:'Layout notes',host:'docs.example.test',icon:'book',section:'review'}];
let pins,sections,unread,collapsed=false;
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
function reset(){pins=original.map(p=>({...p}));sections=[{key:'preview',title:state==='long-label'?'Development previews and environments for mobile layout validation':'Preview'},{key:'review',title:'Review'},{key:'empty',title:'Empty section'}];unread=new Set(['dev','pr']);if(state==='empty'){pins=[];unread.clear()}if(state==='ungrouped'){sections=[];pins.forEach(p=>p.section=null)}collapsed=false;}
function row(p,chat=false){const read=!unread.has(p.key),prefix=(chat?'chat':'menu')+'-'+p.key;return `<div class="row ${read?'read':''}" data-key="${p.key}" data-dc-id="${prefix}-row"><span class="resource" data-dc-id="${prefix}-icon">${icon(p.icon)}<span class="dot"></span></span><div class="copy"><button class="link" data-open="${p.key}" aria-label="Open ${esc(p.title)}${read?'':', unread update'}" data-dc-id="${prefix}-link"><span class="title">${esc(p.title)}</span></button><span class="metadata">${chat?(p.reason?'Updated':'Added')+' · ':''}${p.host}</span>${p.reason?`<div class="message" data-dc-id="${prefix}-message">${esc(p.reason)}</div>`:''}</div>${chat?'':`<button class="icon-button ack" data-read="${p.key}" title="Mark as read" aria-label="Mark ${esc(p.title)} as read" data-dc-id="${prefix}-read" ${read?'disabled':''}>${icon('check')}</button>`}</div>`}
function group(section){const members=pins.filter(p=>p.section===(section?.key??null));if(!members.length)return '';const key=section?.key??'unsectioned';return `<section class="group" data-dc-id="group-${key}" ${section?`aria-labelledby="heading-${key}"`:''}>${section?`<h2 class="section-title" id="heading-${key}" data-dc-id="heading-${key}">${esc(section.title)}</h2>`:''}${members.map(p=>row(p)).join('')}</section>`}
function render(){document.querySelectorAll('[data-count]').forEach(e=>e.textContent='Pins'+(unread.size?' ('+unread.size+')':''));document.querySelectorAll('[data-mark-all]').forEach(e=>e.disabled=!unread.size);if(isChat){document.querySelector('.chat-body').innerHTML=pins.filter(p=>['dev','pr','notes'].includes(p.key)).map(p=>row(p,true)).join('');document.querySelector('.chat-body').hidden=collapsed;document.querySelectorAll('[data-collapse]').forEach(e=>e.setAttribute('aria-expanded',String(!collapsed)));const button=document.querySelector('[data-chevron]');button.innerHTML=icon(collapsed?'right':'down');button.setAttribute('aria-label',collapsed?'Expand pins':'Collapse pins');}else{document.querySelector('.sample').classList.toggle('is-empty',!pins.length);document.querySelector('.toolbar').hidden=!pins.length;document.querySelector('.pin-list').innerHTML=pins.length?group(null)+sections.map(group).join(''):'<div class="empty" data-dc-id="empty-message">No pins yet</div>';}}
function feedback(text){document.querySelector('[data-feedback]').textContent=text;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-read')||b.hasAttribute('data-open')){unread.delete(b.dataset.read??b.dataset.open);feedback('Simulated acknowledgment. Group order stays the same.');}else if(b.hasAttribute('data-mark-all')){unread.clear();feedback('Marked every update read across sections.');}else if(b.hasAttribute('data-reset')){reset();feedback('Reset prototype. Live pins are unchanged.');}else if(b.hasAttribute('data-remove-section')){sections=sections.filter(s=>s.key!=='review');pins.forEach(p=>{if(p.section==='review')p.section=null});feedback('Review section removed; its pins moved to the top. No pins deleted or new notifications created.');}else if(b.hasAttribute('data-ungroup')){pins.forEach(p=>p.section=null);feedback('All pins are unsectioned. Empty section headings are hidden.');}else if(b.hasAttribute('data-named-only')){pins.forEach(p=>{if(p.section===null)p.section='preview'});feedback('No unsectioned pins: the menu starts with the Preview heading.');}else if(b.hasAttribute('data-collapse')){collapsed=!collapsed;}else return;render();});reset();render();
